import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { SoftwarePackageService } from '../../services/software-package.service';
import { OrderService } from '../../services/order.service';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-order',
  templateUrl: './order.component.html',
  styleUrls: ['./order.component.css']
})
export class OrderComponent implements OnInit {
  package: SoftwarePackage | null = null;
  loading = false;
  quantity = 1;
  contactPhone = '';
  contactEmail = '';
  contactAddress = '';
  itemDescription = '';
  placing = false;
  currentImage = '';
  successMessage = '';
  errorMessage = '';

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private softwarePackageService: SoftwarePackageService,
    private orderService: OrderService
  ) {}

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.fetchPackage(id);
  }

  fetchPackage(id: number): void {
    this.loading = true;
    this.errorMessage = '';
    this.softwarePackageService.fetchPackageById(id).then((data: SoftwarePackage | null) => {
      this.package = data;
      if (!data) {
        this.errorMessage = 'Software package not found';
      }
    }).finally(() => {
      this.loading = false;
    });
  }

  async placeOrder(): Promise<void> {
    if (!this.package) return;
    if (!this.contactPhone || !this.contactEmail || !this.contactAddress) {
      this.errorMessage = 'Please fill in all contact details (phone, email, address)';
      return;
    }
    this.placing = true;
    this.successMessage = '';
    this.errorMessage = '';
    try {
      await this.orderService.placeOrder(this.package.id, this.quantity, this.contactPhone, this.contactEmail, this.contactAddress, this.itemDescription);
      this.successMessage = 'Order placed successfully! A confirmation has been sent.';
      setTimeout(() => {
        this.router.navigate(['/my-orders']);
      }, 1500);
    } catch (err: any) {
      this.errorMessage = err.error?.error || 'Failed to place order. Please try again.';
    } finally {
      this.placing = false;
    }
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="page-header">
    <div class="header-content">
      <button (click)="goBack()" class="inline-flex items-center text-sm text-gray-600 hover:text-primary">
        <svg class="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Back to Packages
      </button>
      <span class="text-sm font-medium text-gray-500">Place Order</span>
    </div>
  </header>

  <div class="page-container">
    <div *ngIf="loading" class="flex justify-center py-16">
      <div class="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
    </div>

    <div *ngIf="!loading && errorMessage" class="text-center py-16">
      <div class="text-red-500 mb-3">
        <svg class="w-6 h-6 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-sm text-red-600">{{ errorMessage }}</p>
    </div>

    <div *ngIf="!loading && !errorMessage && package" class="card-base">
      <div class="p-6 lg:p-8">
        <div class="flex flex-col lg:flex-row gap-8 items-start lg:items-center">
          <div class="lg:w-1/2">
            <div class="relative aspect-square bg-gray-100 overflow-hidden rounded-lg mb-4">
              <img [src]="package.thumbnail || package.images?.[0] || 'https://via.placeholder.com/300'" [alt]="package.title" class="w-full h-full object-cover" />
            </div>
            <div *ngIf="package.images && package.images.length > 1" class="grid grid-cols-4 gap-2 mb-6">
              <div *ngFor="let image of package.images; let i = index" (click)="currentImage = image" [ngClass]="{ 'border-primary': currentImage === image, 'border-transparent hover:border-gray-300': currentImage !== image }" class="aspect-square rounded overflow-hidden bg-gray-100 cursor-pointer border-2 transition-colors">
                <img [src]="image" [alt]="package.title + ' ' + (i + 1)" class="w-full h-full object-cover" />
              </div>
            </div>
          </div>

          <div class="lg:w-1/2 flex flex-col justify-center w-full">
            <h1 class="text-xl font-bold text-gray-900 mb-2">{{ package.title }}</h1>
            <p class="text-gray-600 mb-6 leading-relaxed text-sm">{{ package.description }}</p>

            <div class="mb-6">
              <label class="form-label">Quantity</label>
              <input [(ngModel)]="quantity" name="quantity" type="number" min="1" [max]="package.stock || 1" class="w-20 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
            </div>

            <div class="mb-6">
              <label class="form-label">Contact Phone <span class="text-red-500">*</span></label>
              <input [(ngModel)]="contactPhone" name="contactPhone" type="tel" placeholder="e.g., +1 234 567 8900"
                class="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
            </div>

            <div class="mb-6">
              <label class="form-label">Contact Email <span class="text-red-500">*</span></label>
              <input [(ngModel)]="contactEmail" name="contactEmail" type="email" placeholder="you@example.com"
                class="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
            </div>

            <div class="mb-6">
              <label class="form-label">Delivery Address <span class="text-red-500">*</span></label>
              <textarea [(ngModel)]="contactAddress" name="contactAddress" rows="2" placeholder="Street, City, State, ZIP"
                class="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all"></textarea>
            </div>

            <div *ngIf="successMessage" class="mb-4 p-3 bg-green-50 border border-green-100 rounded-md">
              <p class="text-xs text-green-700 font-medium">{{ successMessage }}</p>
            </div>

            <div *ngIf="errorMessage" class="mb-4 p-3 bg-red-50 border border-red-100 rounded-md">
              <p class="text-xs text-red-600">{{ errorMessage }}</p>
            </div>

            <button (click)="placeOrder()" [disabled]="placing || quantity < 1" class="w-full btn-primary shadow-sm">
              <span *ngIf="placing" class="flex items-center justify-center gap-2">
                <svg class="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                Placing Order...
              </span>
              <span *ngIf="!placing">Place Order</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
